package io.jevopt.analyzers;
import java.nio.file.Path; import java.util.*;
public final class ClaudeCliAnalyzer extends ProcessAnalyzer { public ClaudeCliAnalyzer(Path executable,String model,String apiKeyEnv){super("claude",executable,List.of("--print","--bare","--restricted","--tools","","--disallowedTools","mcp__*","--strict-mcp-config","--no-session-persistence","--permission-prompts","none","--model",model,"--output-format","json","--json-schema",StrictAnalyzerJson.SCHEMA),require(apiKeyEnv));} private static String require(String x){if(!"ANTHROPIC_API_KEY".equals(x))throw new IllegalArgumentException("Explicit ANTHROPIC_API_KEY reference required");return x;} @Override protected AnalyzerResult parse(Path temp,String stdout)throws AnalyzerException{return StrictAnalyzerJson.parseClaude(stdout,id());} }
